1	// Pure cart logic, shared by the page (app.js) and the unit tests. Prices are integer cents.
2	
3	export const MAX_QTY = 10;
4	export const MIN_QTY = 1;
5	export const PROMOS = { SAVE10: 0.10 };
6	
7	export const DEFAULT_ITEMS = [
8	  { sku: 'KB-200', name: 'Ergonomic keyboard', price: 12900, qty: 1 },
9	  { sku: 'MN-27', name: '27-inch monitor', price: 89900, qty: 1 },
10	  { sku: 'CB-C2', name: 'USB-C cable (2 m)', price: 1250, qty: 2 },
11	];
12	
13	export function formatMoney(cents) {
14	  return '$' + (cents / 100).toFixed(2);
15	}
16	
17	export function lineTotal(item) {
18	  return item.price * item.qty;
19	}
20	
21	export function subtotal(items) {
22	  return items.reduce((s, it) => s + lineTotal(it), 0);
23	}
24	
25	export function increment(item) {
26	  if (item.qty <= MAX_QTY) item.qty += 1;
27	  return item;
28	}
29	
30	export function decrement(item) {
31	  if (item.qty >= MIN_QTY) item.qty -= 1;
32	  return item;
33	}
34	
35	// Returns the promo rate for a code, or null if the code is unknown. Codes are case-insensitive.
36	export function promoRate(code) {
37	  const rate = PROMOS[String(code).trim().toUpperCase()];
38	  return rate === undefined ? null : rate;
39	}
40	
41	export function discountFor(items, rate) {
42	  return Math.round(subtotal(items) * rate);
43	}
44

1	import { DEFAULT_ITEMS, MAX_QTY, MIN_QTY, formatMoney, lineTotal, subtotal, increment, decrement, promoRate, discountFor } from './cart.js';
2	
3	const STORAGE_KEY = 'cart:v1';
4	
5	const state = {
6	  items: load(),
7	  discount: 0, // cents, set when a promo code is applied
8	  promoError: '',
9	};
10	
11	function load() {
12	  try {
13	    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
14	    if (Array.isArray(saved)) return saved;
15	  } catch {}
16	  return structuredClone(DEFAULT_ITEMS);
17	}
18	
19	function save() {
20	  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state.items)); } catch {}
21	}
22	
23	const $ = (sel) => document.querySelector(sel);
24	
25	function renderLine(item) {
26	  const li = document.createElement('li');
27	  li.className = 'line';
28	  li.innerHTML = `
29	    <div class="line-name">${item.name}<span class="sku">${item.sku}</span></div>
30	    <div class="stepper">
31	      <button type="button" class="dec" aria-label="Decrease quantity" ${item.qty < MIN_QTY ? 'disabled' : ''}>−</button>
32	      <output class="qty" aria-live="polite">${item.qty}</output>
33	      <button type="button" class="inc" aria-label="Increase quantity" ${item.qty > MAX_QTY ? 'disabled' : ''}>+</button>
34	    </div>
35	    <div class="line-total">${formatMoney(lineTotal(item))}</div>
36	    <button type="button" class="remove">Remove</button>`;
37	  li.querySelector('.inc').addEventListener('click', () => { increment(item); render(); });
38	  li.querySelector('.dec').addEventListener('click', () => { decrement(item); render(); });
39	  li.querySelector('.remove').addEventListener('click', () => {
40	    state.items = state.items.filter((x) => x !== item);
41	    save();
42	    render();
43	  });
44	  return li;
45	}
46	
47	function render() {
48	  const list = $('#lines');
49	  list.replaceChildren(...state.items.map(renderLine));
50	  const empty = state.items.length === 0;
51	  $('#empty').hidden = !empty;
52	  $('#summary').classList.toggle('is-hidden', empty);
53	
54	  const sub = subtotal(state.items);
55	  $('#subtotal').textContent = formatMoney(sub);
56	  $('#discount-row').hidden = state.discount === 0;
57	  $('#discount').textContent = '−' + formatMoney(state.discount);
58	  $('#total').textContent = formatMoney(sub - state.discount);
59	  $('#promo-error').textContent = state.promoError;
60	  $('#promo-error').hidden = !state.promoError;
61	}
62	
63	$('#promo-form').addEventListener('submit', (e) => {
64	  e.preventDefault();
65	  const rate = promoRate($('#promo').value);
66	  if (rate === null) {
67	    state.promoError = 'Code not recognised';
68	  } else {
69	    state.discount = discountFor(state.items, rate);
70	  }
71	  render();
72	});
73	
74	render();
75

1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { DEFAULT_ITEMS, subtotal, lineTotal, increment, decrement, promoRate, discountFor, formatMoney } from '../public/cart.js';
4	
5	const fresh = () => structuredClone(DEFAULT_ITEMS);
6	
7	test('subtotal of the default cart', () => {
8	  assert.equal(subtotal(fresh()), 12900 + 89900 + 2 * 1250);
9	});
10	
11	test('increment and decrement change the quantity', () => {
12	  const item = { price: 500, qty: 2 };
13	  increment(item);
14	  assert.equal(item.qty, 3);
15	  decrement(item);
16	  decrement(item);
17	  assert.equal(item.qty, 1);
18	  assert.equal(lineTotal(item), 500);
19	});
20	
21	test('SAVE10 gives 10 percent off, any case', () => {
22	  assert.equal(promoRate('SAVE10'), 0.10);
23	  assert.equal(promoRate(' save10 '), 0.10);
24	  assert.equal(promoRate('FREESHIP'), null);
25	  assert.equal(discountFor(fresh(), 0.10), 10530);
26	});
27	
28	test('formatMoney shows dollars and cents', () => {
29	  assert.equal(formatMoney(1250), '$12.50');
30	  assert.equal(formatMoney(5), '$0.05');
31	});
