import { chromium } from 'playwright-core';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.goto('http://127.0.0.1:4173/');

const log = (...a) => console.log(...a);

// --- Stepper boundary test: click + on keyboard line 12 times ---
const incBtn = page.locator('.line').nth(0).locator('.inc');
const decBtn = page.locator('.line').nth(0).locator('.dec');
const qtyOut = page.locator('.line').nth(0).locator('.qty');

for (let i = 0; i < 12; i++) {
  await incBtn.click({ force: true }).catch(() => {});
}
log('After 12 clicks on +, qty =', await qtyOut.textContent(), 'inc disabled?', await incBtn.isDisabled());

// reset by reloading default state via localStorage clear
await page.evaluate(() => localStorage.clear());
await page.reload();

// --- Decrement boundary test ---
for (let i = 0; i < 5; i++) {
  await decBtn.click({ force: true }).catch(() => {});
}
log('After 5 clicks on - (qty starts at 1), qty =', await qtyOut.textContent(), 'dec disabled?', await decBtn.isDisabled());

await page.evaluate(() => localStorage.clear());
await page.reload();

// --- Check disabled state exactly at boundaries by setting qty via UI clicks ---
// bring qty to 10 (starts at 1, need 9 clicks)
for (let i = 0; i < 9; i++) await incBtn.click();
log('qty after 9 clicks (expect 10):', await qtyOut.textContent(), '| inc.disabled at qty=10 (should be true):', await incBtn.isDisabled());
await incBtn.click({ force: true }).catch(()=>{});
log('qty after 1 more click at qty=10 (should stay 10):', await qtyOut.textContent());

await page.evaluate(() => localStorage.clear());
await page.reload();
log('dec.disabled at qty=1 (should be true):', await decBtn.isDisabled());

// --- Remove + empty state ---
await page.evaluate(() => localStorage.clear());
await page.reload();
const removeButtons = page.locator('.remove');
let count = await removeButtons.count();
while (count > 0) {
  await removeButtons.first().click();
  count = await removeButtons.count();
}
log('Empty message visible?', await page.locator('#empty').isVisible());
log('Summary hidden?', await page.locator('#summary').evaluate(el => el.classList.contains('is-hidden')));
log('Checkout visible after empty?', await page.locator('.checkout').isVisible());

await page.evaluate(() => localStorage.clear());
await page.reload();

// --- Promo code test ---
await page.fill('#promo', 'bogus');
await page.click('button[type=submit]');
log('Unknown code error text:', await page.locator('#promo-error').textContent(), 'visible:', await page.locator('#promo-error').isVisible());

await page.fill('#promo', 'save10');
await page.click('button[type=submit]');
log('Valid code (lowercase) error hidden now?', !(await page.locator('#promo-error').isVisible()));
log('Discount row text:', await page.locator('#discount').textContent());
log('Total text:', await page.locator('#total').textContent());
log('Subtotal text:', await page.locator('#subtotal').textContent());

// increase qty after applying promo, check discount follows
await incBtn.click();
log('After qty+1 with promo applied -> Subtotal:', await page.locator('#subtotal').textContent(), 'Discount:', await page.locator('#discount').textContent(), 'Total:', await page.locator('#total').textContent());

// --- Persistence ---
await page.evaluate(() => localStorage.clear());
await page.reload();
await incBtn.click();
await incBtn.click();
const qtyBefore = await qtyOut.textContent();
await page.reload();
const qtyAfter = await qtyOut.textContent();
log('Persistence: qty before reload =', qtyBefore, ' qty after reload =', qtyAfter);

// --- Horizontal scroll check at 375px ---
await page.setViewportSize({ width: 375, height: 800 });
const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
log('Horizontal overflow px at 375 viewport (should be 0):', overflow);
const checkoutBox = await page.locator('.checkout').boundingBox();
log('Checkout button box at 375 viewport:', checkoutBox, '| viewport width 375, fully within?', checkoutBox && (checkoutBox.x + checkoutBox.width <= 375));

// --- Layout breakpoint check at 768px ---
await page.setViewportSize({ width: 768, height: 900 });
await page.reload();
const itemsBox = await page.locator('.items').boundingBox();
const summaryBox = await page.locator('.summary').boundingBox();
log('At 768px: items box:', itemsBox, 'summary box:', summaryBox);
log('Summary to the right of items? (summary.x >= items.x + items.width):', summaryBox.x >= itemsBox.x + itemsBox.width - 1);

await browser.close();
